SELECT COUNT(DISTINCT customer_id) AS unique_customers
FROM sales
WHERE customer_id IS NOT NULL;

SELECT AVG(order_total) AS average_order_value
FROM (
    SELECT invoice, SUM(revenue) AS order_total
    FROM sales
    GROUP BY invoice
);

SELECT 
    COUNT(DISTINCT CASE WHEN is_cancelled THEN invoice END) * 100.0 / COUNT(DISTINCT invoice) AS cancelled_invoice_percentage
FROM transactions;
